            }
          },
          "removedRecordIndices": {
            "type": "array",
            "items": {
              "type": "integer",
              "minimum": 0
            }
          },
          "unitsDelta": {
            "anyOf": [
              {
                "type": "string",
                "pattern": "^-?(0|[1-9][0-9]*)$"
              },
              {
                "type": "null"
              }
            ]
          }
        },
        "required": [
          "from",
          "to",
          "revenueDelta",
          "commonShopRanks",
          "topShopRetention",
          "removedRecordIndices",
          "unitsDelta"
        ]
      }
    },
    "rendererVersion": {
      "const": "metric-draft-vi-v1"
    }
  },
  "required": [
    "contractVersion",
    "methodVersion",
    "rounding",
    "status",
    "verification",
    "inputSha256",
    "input",
    "labelIssues",
    "scopes",
    "comparisons",
    "rendererVersion"
  ],
  "$defs": {
    "Total": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "value": {
          "anyOf": [
            {
              "type": "string",
              "pattern": "^(0|[1-9][0-9]{0,49})$"
            },
            {
              "type": "null"
            }
          ]
        },
        "observedCount": {
          "type": "integer",
          "minimum": 0
        },
        "missingCount": {
          "type": "integer",
          "minimum": 0
        },
        "nonExactCount": {
          "type": "integer",
          "minimum": 0
        },
        "complete": {
          "type": "boolean"
        }
      },
      "required": [
        "value",
        "observedCount",
        "missingCount",
        "nonExactCount",
        "complete"
      ]
    },
    "Ratio": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "numerator": {
          "type": "string",
          "pattern": "^(0|[1-9][0-9]{0,49})$"
