      },
      "required": [
        "numerator",
        "denominator",
        "percent"
      ]
    },
    "Shop": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "shopKey": {
          "type": "string",
          "minLength": 1,
          "maxLength": 300
        },
        "revenue": {
          "$ref": "#/$defs/Total"
        },
        "units": {
          "$ref": "#/$defs/Total"
        }
      },
      "required": [
        "shopKey",
        "revenue",
        "units"
      ]
    },
    "Scope": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "key": {
          "enum": [
            "all",
            "wide",
            "core"
          ]
        },
        "status": {
          "enum": [
            "CALCULATED",
            "BLOCKED_LABELS"
          ]
        },
        "recordIndices": {
          "type": "array",
          "items": {
            "type": "integer",
            "minimum": 0
          }
        },
        "listingCount": {
          "type": "integer",
          "minimum": 0
        },
        "shopCount": {
          "type": "integer",
          "minimum": 0
        },
        "revenue": {
          "$ref": "#/$defs/Total"
        },
        "units": {
          "$ref": "#/$defs/Total"
        },
        "warnings": {
          "type": "array",
          "items": {
            "enum": [
              "EMPTY_SCOPE",
              "MISSING_REVENUE",
              "MISSING_UNITS",
              "NON_EXACT_REVENUE",
              "NON_EXACT_UNITS",
              "ZERO_REVENUE",
              "LABELS_REQUIRE_ADJUDICATION"
            ]
          }
        },
        "shops": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/Shop"
          }
        },
        "groups": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "group": {
                "type": "string",
                "minLength": 1,
                "maxLength": 128
              },
              "listingCount": {
                "type": "integer",
                "minimum": 0
              },
              "revenue": {
                "$ref": "#/$defs/Total"
              },
              "units": {
                "$ref": "#/$defs/Total"
              },
              "revenueShare": {
                "anyOf": [
                  {
                    "$ref": "#/$defs/Ratio"
                  },
                  {
                    "type": "null"
                  }
                ]
              }
            },
            "required": [
              "group",
              "listingCount",
              "revenue",
              "units",
              "revenueShare"
            ]
          }
        },
        "concentration": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "k": {
                "enum": [
                  1,
                  3,
                  10
                ]
              },
              "usedShopCount": {
                "type": "integer",
                "minimum": 0
              },
              "share": {
                "anyOf": [
                  {
                    "$ref": "#/$defs/Ratio"
                  },
                  {
                    "type": "null"
                  }
                ]
              }
            },
            "required": [
              "k",
              "usedShopCount",
              "share"
            ]
          }
        },
        "withoutTopShop": {
          "anyOf": [
            {
              "type": "object",
              "additionalProperties": false,
