                    {
                      "$ref": "#/$defs/Ratio"
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "shops": {
                  "type": "array",
                  "items": {
                    "$ref": "#/$defs/Shop"
                  }
                },
                "concentration": {
                  "type": "array",
                  "items": {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                      "k": {
                        "enum": [
                          1,
                          3,
                          10
                        ]
                      },
                      "usedShopCount": {
                        "type": "integer",
                        "minimum": 0
                      },
                      "share": {
                        "anyOf": [
                          {
                            "$ref": "#/$defs/Ratio"
                          },
                          {
                            "type": "null"
                          }
                        ]
                      }
                    },
                    "required": [
                      "k",
                      "usedShopCount",
                      "share"
                    ]
                  }
